mapper.update:
UPDATE xiangqin_activity
SET view_count = view_count + 1
WHERE id = #{id}

mapper.select:
SELECT 
    a.*,
    h.hongniang_name,
    h.avatar as hongniang_avatar,
    h.level as hongniang_level
FROM xiangqin_activity a
LEFT JOIN hongniang_info h ON a.hongniang_id = h.id


        AND a.status = #{status}


        AND a.hongniang_id = #{hongniangId}


        AND a.activity_type = #{activityType}


ORDER BY a.create_time DESC
LIMIT #{offset}, #{limit}
